import { useEffect, useMemo, useRef, useState } from "react";
export const useChartTicks = () => {
    const chartRef = useRef(null);
    const [chartWidth, setChartWidth] = useState(718);
    useEffect(() => {
        if (!chartRef.current) {
            return () => { };
        }
        const applyWidth = () => {
            if (!chartRef.current) {
                return;
            }
            const { width } = chartRef.current.getBoundingClientRect();
            setChartWidth(width);
        };
        applyWidth();
        const handleResize = () => {
            applyWidth();
        };
        window.addEventListener("resize", handleResize);
        return () => {
            window.removeEventListener("resize", handleResize);
        };
    }, []);
    const ticks = useMemo(() => {
        const xlSize = 1102;
        const lSize = 718;
        const mSize = 526;
        if (chartWidth < mSize) {
            return 4;
        }
        if (chartWidth < lSize) {
            return 6;
        }
        if (chartWidth < xlSize) {
            return 8;
        }
        return 12;
    }, [chartWidth]);
    return { chartRef, ticks };
};
